// n8n · F12 · nodo "Trabajos" (Code, una vez para todos los elementos).
// Arma la lista de consultas a Google que luego se guardan en Supabase.
//  - Cada hora: Google Analytics de los últimos 3 días (los datos de GA4 se ajustan durante ~48 h).
//  - A las 7 a. m. de Bogotá: además, Search Console de los últimos 6 días (Google publica con 2-3 días de retraso).
//  - Corrido a mano: histórico completo por tramos de 31 días (GA4 desde 2024-01-01, Search Console 16 meses).
const PROPIEDAD_GA4 = '333145660';
const SITIO_GSC = 'sc-domain:wiptool.com';
const INICIO_GA4 = '2024-01-01';

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
const manual = !$input.first().json.timestamp; // el disparador de cada hora trae "timestamp"; el manual no

const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const tramos = (desde, hasta, dias) => {
  const out = [];
  for (let a = desde; a <= hasta; a = sumar(a, dias)) { const b = sumar(a, dias - 1); out.push([a, b < hasta ? b : hasta]); }
  return out;
};

const GA4 = {
  ga4_canal_diario: {
    dimensions: ['date', 'sessionDefaultChannelGroup', 'sessionSource', 'sessionMedium', 'sessionCampaignName', 'sessionManualAdContent', 'sessionManualTerm'],
    metrics: ['sessions', 'keyEvents'],
  },
  ga4_evento_diario: { dimensions: ['date', 'eventName', 'customEvent:origen', 'customEvent:correo'], metrics: ['eventCount', 'keyEvents', 'totalUsers'] },
  ga4_pagina_diario: { dimensions: ['date', 'landingPage'], metrics: ['sessions', 'keyEvents'] },
  ga4_audiencia_diario: { dimensions: ['date', 'countryId', 'deviceCategory'], metrics: ['sessions', 'keyEvents'] },
};

const trabajos = [];
for (const [desde, hasta] of manual ? tramos(INICIO_GA4, hoy, 31) : [[sumar(hoy, -2), hoy]]) {
  for (const [tabla, r] of Object.entries(GA4)) {
    trabajos.push({
      fuente: 'ga4', tabla, desde, hasta, sitio: null,
      url: `https://analyticsdata.googleapis.com/v1beta/properties/${PROPIEDAD_GA4}:runReport`,
      body: {
        dateRanges: [{ startDate: desde, endDate: hasta }],
        dimensions: r.dimensions.map((name) => ({ name })),
        metrics: r.metrics.map((name) => ({ name })),
        limit: 250000,
      },
    });
  }
}

if (manual || hora === 7) {
  // Un mismo dominio en Search Console: se separa por el host de la página.
  const SITIOS = { 'wiptool.com': 'notContains', 'platform.wiptool.com': 'contains' };
  const TABLAS = { gsc_pagina_diario: ['date', 'page'], gsc_consulta_diario: ['date', 'query'] };
  for (const [desde, hasta] of manual ? tramos(sumar(hoy, -486), sumar(hoy, -1), 31) : [[sumar(hoy, -6), sumar(hoy, -1)]]) {
    for (const [sitio, operador] of Object.entries(SITIOS)) {
      for (const [tabla, dimensions] of Object.entries(TABLAS)) {
        trabajos.push({
          fuente: 'gsc', tabla, desde, hasta, sitio,
          url: `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(SITIO_GSC)}/searchAnalytics/query`,
          body: {
            startDate: desde, endDate: hasta, dimensions, rowLimit: 25000, dataState: 'all',
            dimensionFilterGroups: [{ filters: [{ dimension: 'page', operator: operador, expression: 'platform.wiptool.com' }] }],
          },
        });
      }
    }
  }
}

return trabajos.map((json) => ({ json }));

// n8n · F12 · nodos "Filas Google" y "Filas Meta" (Code, una vez por elemento).
// Convierte la respuesta de cada API en filas de la tabla de Supabase y arma la llamada a cargar().
const t = $('Trabajos Google').item.json; // el nombre lo pone armar-flujo.cjs
const r = $json;

const fecha = (s) => (s && s.length === 8 ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : s);
const paises = new Intl.DisplayNames(['es'], { type: 'region' });
const pais = (id) => { if (!id || id === '(not set)') return '(sin país)'; try { return paises.of(id) || id; } catch (e) { return id; } };

// Suma las filas que comparten la misma clave (evita claves repetidas al insertar).
function agrupar(filas, claves, sumas) {
  const m = new Map();
  for (const f of filas) {
    const k = claves.map((c) => f[c]).join('\u0001');
    const a = m.get(k);
    if (a) sumas.forEach((s) => { a[s] += f[s]; }); else m.set(k, { ...f });
  }
  return [...m.values()];
}

let filas = [];
if (t.fuente === 'ga4') {
  const dn = (r.dimensionHeaders || []).map((h) => h.name);
  const mn = (r.metricHeaders || []).map((h) => h.name);
  const regs = (r.rows || []).map((row) => {
    const o = {};
    dn.forEach((n, i) => { o[n] = row.dimensionValues[i].value; });
    mn.forEach((n, i) => { o[n] = Math.round(Number(row.metricValues[i].value) || 0); });
    return o;
  });
  const v = (x) => (x == null ? '' : String(x));
  if (t.tabla === 'ga4_canal_diario') {
    filas = agrupar(regs.map((o) => ({
      fecha: fecha(o.date), canal: v(o.sessionDefaultChannelGroup), fuente: v(o.sessionSource), medio: v(o.sessionMedium),
      campana: v(o.sessionCampaignName), contenido: v(o.sessionManualAdContent), termino: v(o.sessionManualTerm),
      visitas: o.sessions, conversiones: o.keyEvents,
    })), ['fecha', 'canal', 'fuente', 'medio', 'campana', 'contenido', 'termino'], ['visitas', 'conversiones']);
  } else if (t.tabla === 'ga4_evento_diario') {
    filas = agrupar(regs.map((o) => ({
      fecha: fecha(o.date), evento: v(o.eventName), origen: v(o['customEvent:origen']), correo: v(o['customEvent:correo']),
      eventos: o.eventCount, conversiones: o.keyEvents, personas: o.totalUsers,
    })), ['fecha', 'evento', 'origen', 'correo'], ['eventos', 'conversiones', 'personas']);
  } else if (t.tabla === 'ga4_pagina_diario') {
    filas = agrupar(regs.map((o) => ({ fecha: fecha(o.date), pagina: v(o.landingPage) || '(sin página)', visitas: o.sessions, conversiones: o.keyEvents })),
      ['fecha', 'pagina'], ['visitas', 'conversiones']);
  } else if (t.tabla === 'ga4_audiencia_diario') {
    filas = agrupar(regs.map((o) => ({ fecha: fecha(o.date), pais: pais(o.countryId), dispositivo: v(o.deviceCategory), visitas: o.sessions, conversiones: o.keyEvents })),
      ['fecha', 'pais', 'dispositivo'], ['visitas', 'conversiones']);
  }
} else if (t.fuente === 'meta') {
  // Una fila por día y campaña (time_increment=1). Las conversaciones son los chats de WhatsApp iniciados.
  const conversaciones = (acciones) => Math.round(Number(((acciones || []).find((a) => a.action_type === 'onsite_conversion.messaging_conversation_started_7d') || {}).value) || 0);
  filas = agrupar((r.data || []).map((x) => ({
    fecha: x.date_start, campana_id: String(x.campaign_id), campana: x.campaign_name || '', moneda: x.account_currency || 'COP',
    inversion: Number(x.spend) || 0, impresiones: Math.round(Number(x.impressions) || 0), clics: Math.round(Number(x.clicks) || 0),
    conversaciones: conversaciones(x.actions),
  })), ['fecha', 'campana_id'], ['inversion', 'impresiones', 'clics', 'conversaciones']);
} else {
  const campo = t.tabla === 'gsc_pagina_diario' ? 'pagina' : 'consulta';
  filas = agrupar((r.rows || []).map((x) => ({
    fecha: x.keys[0], sitio: t.sitio, [campo]: x.keys[1],
    clics: Math.round(x.clicks || 0), impresiones: Math.round(x.impressions || 0), pos_x_imp: (x.position || 0) * (x.impressions || 0),
  })), ['fecha', 'sitio', campo], ['clics', 'impresiones', 'pos_x_imp']);
}

return { json: { p_tabla: t.tabla, p_desde: t.desde, p_hasta: t.hasta, p_filas: filas, p_fuente: t.fuente, p_sitio: t.sitio } };

// n8n · F12 · nodo "Trabajos Meta" (Code, una vez para todos los elementos).
// Cada hora: Meta Ads de los últimos 3 días (Meta ajusta las cifras durante unas horas).
// Corrido a mano: histórico desde 2025-01-01, por tramos de 31 días.
const CUENTA = 'act_1212455492189816';
const INICIO = '2025-01-01';

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const tramos = (desde, hasta, dias) => {
  const out = [];
  for (let a = desde; a <= hasta; a = sumar(a, dias)) { const b = sumar(a, dias - 1); out.push([a, b < hasta ? b : hasta]); }
  return out;
};

return (manual ? tramos(INICIO, hoy, 31) : [[sumar(hoy, -2), hoy]]).map(([desde, hasta]) => {
  // El Code de n8n no tiene URLSearchParams: se arma a mano.
  const qs = Object.entries({
    level: 'campaign',
    time_increment: '1',
    time_range: JSON.stringify({ since: desde, until: hasta }),
    fields: 'campaign_id,campaign_name,spend,impressions,clicks,actions,account_currency',
    limit: '1000',
  }).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  return { json: { fuente: 'meta', tabla: 'meta_campana_diario', desde, hasta, sitio: null,
    url: `https://graph.facebook.com/v23.0/${CUENTA}/insights?${qs}` } };
});

