// n8n · F12 · nodo "Trabajos TRM" (Code, una vez para todos los elementos).
// TRM oficial de datos.gov.co (no pide clave). A las 7 a. m. carga los últimos 10 días; a mano, desde 2024.
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Bogota', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
const manual = !$input.first().json.timestamp;
if (!manual && hora !== 7) return [];

const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const desde = manual ? '2024-01-01' : sumar(hoy, -10);
const donde = encodeURIComponent(`vigenciahasta >= '${desde}T00:00:00'`);
return [{ json: { fuente: 'trm', tabla: 'trm_diaria', desde, hasta: hoy, sitio: null,
  url: `https://www.datos.gov.co/resource/32sa-8pi3.json?$order=vigenciadesde&$limit=5000&$where=${donde}` } }];

// n8n · F12 · nodo "Filas TRM" (Code, una vez para todos los elementos).
// datos.gov.co devuelve tramos de vigencia (un fin de semana es un solo tramo); aquí se abren en un valor por día.
const t = $('Trabajos TRM').first().json;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const porDia = new Map();
for (const { json: x } of $input.all()) {
  if (!x || !x.vigenciadesde) continue;
  const valor = Number(x.valor);
  for (let d = x.vigenciadesde.slice(0, 10); d <= x.vigenciahasta.slice(0, 10); d = sumar(d, 1)) {
    if (d >= t.desde && d <= t.hasta) porDia.set(d, valor);
  }
}
const filas = [...porDia].map(([fecha, valor]) => ({ fecha, valor }));
const fechas = filas.map((f) => f.fecha).sort();
if (!filas.length) return [];
return [{ json: { p_tabla: 'trm_diaria', p_desde: fechas[0], p_hasta: fechas[fechas.length - 1], p_filas: filas, p_fuente: 'trm', p_sitio: null } }];

// n8n · F12 · nodo "Trabajos Brevo" (Code, una vez para todos los elementos).
// Cada hora: correos de las automatizaciones de los últimos 3 días y todas las campañas masivas enviadas.
// Corrido a mano: correos de los últimos 30 días (más no cabe en la memoria del plan de n8n junto con el histórico de Google).
// Los eventos se piden día por día (con un día de margen a cada lado, porque Brevo no usa la hora de Bogotá)
// y en páginas de LIMITE; "Filas Brevo" los junta y guarda solo los días del rango.
const BASE = 'https://api.brevo.com/v3';
const LIMITE = 2500;
const PAGINAS = 2; // hasta 5.000 eventos por día; si la última página llega llena, "Filas Brevo" avisa con un error

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

const desde = sumar(hoy, manual ? -29 : -2);
const eventos = [];
for (let dia = sumar(desde, -1); dia <= hoy; dia = sumar(dia, 1)) {
  for (let p = 0; p < PAGINAS; p++) {
    eventos.push({ json: {
      fuente: 'brevo', tabla: 'brevo_evento_diario', desde, hasta: hoy, sitio: null, dia, pagina: p, ultima: p === PAGINAS - 1, limite: LIMITE,
      url: `${BASE}/smtp/statistics/events?limit=${LIMITE}&offset=${p * LIMITE}&sort=desc&startDate=${dia}&endDate=${dia}`,
    } });
  }
}

const campanas = { json: {
  fuente: 'brevo', tabla: 'brevo_campana', desde: '2000-01-01', hasta: '2100-12-31', sitio: null,
  url: `${BASE}/emailCampaigns?type=classic&status=sent&statistics=globalStats&excludeHtmlContent=true&limit=100&offset=0`,
} };

return [...eventos, campanas];

// n8n · F12 · nodo "Filas Brevo" (Code, una vez para todos los elementos).
// Junta las páginas de eventos de todos los días en una sola carga (mensajes distintos por día, asunto y evento)
// y arma aparte la carga de las campañas masivas.
const trabajos = $('Trabajos Brevo').all();
const respuestas = $input.all();
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });

const salida = [];
const grupos = new Map();
let rango = null;

respuestas.forEach((r, i) => {
  const t = trabajos[i].json;
  if (t.tabla === 'brevo_evento_diario') {
    rango = { desde: t.desde, hasta: t.hasta };
    const ev = r.json.events || [];
    if (t.ultima && ev.length >= t.limite) throw new Error(`Brevo tiene más de ${(t.pagina + 1) * t.limite} eventos el ${t.dia}: hay que subir PAGINAS en "Trabajos Brevo"`);
    for (const e of ev) {
      const f = dia.format(new Date(e.date));
      if (f < t.desde || f > t.hasta) continue;
      const k = [f, String(e.subject || '').trim(), e.event].join('\u0001');
      if (!grupos.has(k)) grupos.set(k, new Set());
      grupos.get(k).add(e.messageId || `${e.email}|${e.date}`);
    }
  } else {
    // Campañas masivas enviadas, con sus cifras acumuladas.
    const filas = (r.json.campaigns || []).filter((c) => c.sentDate).map((c) => {
      const s = (c.statistics && c.statistics.globalStats) || {};
      return { fecha: dia.format(new Date(c.sentDate)), campana_id: String(c.id), campana: c.name || '', asunto: c.subject || '',
        enviados: Math.round(s.sent || 0), entregados: Math.round(s.delivered || 0), aperturas: Math.round(s.uniqueViews || 0),
        clics: Math.round(s.uniqueClicks || 0), desuscritos: Math.round(s.unsubscriptions || 0),
        rebotes: Math.round((s.hardBounces || 0) + (s.softBounces || 0)) };
    });
    salida.push({ json: { p_tabla: 'brevo_campana', p_desde: t.desde, p_hasta: t.hasta, p_filas: filas, p_fuente: 'brevo', p_sitio: null } });
  }
});

if (rango) {
  const filas = [...grupos.entries()].map(([k, ids]) => { const [f, asunto, evento] = k.split('\u0001'); return { fecha: f, asunto, evento, mensajes: ids.size }; });
  salida.unshift({ json: { p_tabla: 'brevo_evento_diario', p_desde: rango.desde, p_hasta: rango.hasta, p_filas: filas, p_fuente: 'brevo', p_sitio: null } });
}
return salida;

// Con la lista de campañas arma los pedidos: el total acumulado de cada campaña y los leads calientes recientes.
const BASE = 'https://api.explee.com/public/api/v1/autogtm';
const campanas = $input.first().json.campaigns || [];
const manual = $('Trabajos Explee').first().json.manual;
const desde = manual ? '2020-01-01T00:00:00Z' : new Date(Date.now() - 3 * 86400000).toISOString();
return [
  ...campanas.map((c) => ({ json: { tipo: 'analitica', campana_id: String(c.id), campana: c.name || '',
    url: `${BASE}/campaigns/${c.id}/analytics?period=all` } })),
  { json: { tipo: 'leads', url: `${BASE}/hot-leads?limit=200&since=${encodeURIComponent(desde)}` } },
];

// Junta las respuestas: el total acumulado de cada campaña en este momento y los leads calientes.
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const ahora = new Date();
const hoy = dia.format(ahora);
const pedidos = $('Pedidos Explee').all();
const respuestas = $input.all();
const num = (v) => (v == null || v === '' ? 0 : Number(v) || 0);

// Deja solo lo que escribió la persona: corta el correo citado ("El ... escribió:", "On ... wrote:", líneas con ">").
const propio = (texto) => {
  const lineas = String(texto || '').split(/\r?\n/);
  const fin = lineas.findIndex((l) => /^\s*>/.test(l) || /^\s*(El|On)\s.+(escribió|wrote):?\s*$/i.test(l) || /^\s*(El|On)\s.+\d{4}/.test(l));
  const t = (fin >= 0 ? lineas.slice(0, fin) : lineas).join(' ').replace(/\s+/g, ' ').trim();
  return t.length > 500 ? t.slice(0, 497) + '...' : t;
};

const nombres = {};
const acumulado = [];
const leads = new Map();
respuestas.forEach((r, i) => {
  const p = pedidos[i].json;
  if (p.tipo === 'analitica') {
    nombres[p.campana_id] = p.campana;
    const a = r.json;
    if (a.emails_sent == null) throw new Error(`Explee no devolvió el total de la campaña ${p.campana}: ${JSON.stringify(a).slice(0, 200)}`);
    acumulado.push({ fecha: hoy, momento: ahora.toISOString(), campana_id: p.campana_id, campana: p.campana,
      enviados: num(a.emails_sent), respuestas: num(a.total_replies), leads: num(a.hot_leads), gasto_usd: num(a.spend_usd) });
  } else {
    const lista = r.json.leads || [];
    if (lista.length >= 200) throw new Error('Explee devolvió 200 leads calientes o más (el máximo por pedido): hay que paginar el pedido de leads en "Pedidos Explee"');
    for (const l of lista) leads.set(`${l.email}|${l.company_domain}`, l);
  }
});

const filasLeads = [...leads.entries()].map(([id, l]) => ({
  fecha: l.became_hot_at ? dia.format(new Date(l.became_hot_at)) : null, lead_id: id,
  campana: nombres[l.campaign_id] || String(l.campaign_id || ''), empresa: l.company_name || '', dominio: l.company_domain || '',
  cargo: l.job_title || '', pais: l.country || '', motivo: propio(l.why_hot), nombre: l.name || '', correo: l.email || '',
  linkedin: l.linkedin_url || '', telefono: l.phone || '', nota: l.note || '',
}));

return [
  { json: { p_tabla: 'explee_acumulado', p_desde: hoy, p_hasta: hoy, p_filas: acumulado, p_fuente: 'explee', p_sitio: null } },
  { json: { p_tabla: 'explee_lead', p_desde: hoy, p_hasta: hoy, p_filas: filasLeads, p_fuente: null, p_sitio: null } },
];

const BASE = 'https://wiptool.kommo.com/api/v4';
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const manual = !$input.first().json.timestamp;
const sumar = (f, n) => { const d = new Date(f + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const desde = sumar(hoy, manual ? -364 : -2);
const unix = Math.floor(new Date(desde + 'T00:00:00-05:00').getTime() / 1000); // medianoche de Bogotá
const PAG_LEADS = 4, PAG_EVENTOS = manual ? 20 : 10; // 250 oportunidades y 100 cambios por página (10: los movimientos masivos del ciclo de vida)
// Los chats sin aceptar (etapa "Leads entrantes") no salen en /leads: hay que pedirlos por la etapa.
const EMBUDO = 14551307, ETAPA_ENTRANTES = 112413247;

return [
  { json: { tipo: 'etapas', url: `${BASE}/leads/pipelines` } },
  { json: { tipo: 'usuarios', url: `${BASE}/users?limit=250` } },
  { json: { tipo: 'entrantes', url: `${BASE}/leads?limit=250&with=loss_reason&filter[statuses][0][pipeline_id]=${EMBUDO}&filter[statuses][0][status_id]=${ETAPA_ENTRANTES}` } },
  ...Array.from({ length: PAG_LEADS }, (_, i) => ({ json: { tipo: 'leads', pagina: i + 1, ultima: i === PAG_LEADS - 1,
    url: `${BASE}/leads?limit=250&page=${i + 1}&with=loss_reason` } })),
  ...Array.from({ length: PAG_EVENTOS }, (_, i) => ({ json: { tipo: 'eventos', pagina: i + 1, ultima: i === PAG_EVENTOS - 1, desde, hasta: hoy,
    url: `${BASE}/events?limit=100&page=${i + 1}&filter[type]=lead_status_changed&filter[created_at][from]=${unix}` } })),
];

// Junta las páginas y arma tres cargas: etapas, oportunidades y cambios de etapa.
const trabajos = $('Trabajos Kommo').all();
const respuestas = $input.all();
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const fecha = (s) => (s ? dia.format(new Date(s * 1000)) : null);
const iso = (s) => (s ? new Date(s * 1000).toISOString() : null);
// Kommo responde application/hal+json y n8n lo deja como texto en "data"; las páginas vacías llegan sin cuerpo (204).
const cuerpo = (r) => {
  const j = r.json || {};
  if (typeof j.data !== 'string') return j;
  try { return JSON.parse(j.data); } catch (e) { return {}; }
};
const campo = (lead, prueba) => {
  const f = (lead.custom_fields_values || []).find(prueba);
  return f && f.values && f.values[0] ? String(f.values[0].value ?? '') : '';
};

const etapas = [], usuarios = {}, leads = new Map(), eventos = new Map();
let rango = null;
respuestas.forEach((r, i) => {
  const t = trabajos[i].json;
  const e = cuerpo(r)._embedded || {};
  if (t.tipo === 'etapas') {
    for (const p of e.pipelines || []) {
      for (const s of (p._embedded && p._embedded.statuses) || []) {
        etapas.push({ etapa_id: s.id, embudo_id: p.id, nombre: s.name, orden: s.sort,
          tipo: s.id === 142 ? 'ganada' : s.id === 143 ? 'perdida' : s.type === 1 ? 'entrantes' : 'abierta' });
      }
    }
  } else if (t.tipo === 'usuarios') {
    for (const u of e.users || []) usuarios[u.id] = u.name;
  } else if (t.tipo === 'entrantes') {
    const lista = e.leads || [];
    if (lista.length >= 250) throw new Error('Hay más de 250 chats en Leads entrantes: hay que paginar el trabajo "entrantes" en "Trabajos Kommo"');
    for (const l of lista) leads.set(l.id, l);
  } else if (t.tipo === 'leads') {
    const lista = e.leads || [];
    if (t.ultima && lista.length >= 250) throw new Error('Kommo tiene más de 1.000 oportunidades: hay que subir PAG_LEADS en "Trabajos Kommo"');
    for (const l of lista) leads.set(l.id, l);
  } else {
    rango = { desde: t.desde, hasta: t.hasta };
    const lista = e.events || [];
    if (t.ultima && lista.length >= 100) throw new Error('Hay más cambios de etapa de los que se piden: hay que subir PAG_EVENTOS en "Trabajos Kommo"');
    for (const ev of lista) eventos.set(ev.id, ev);
  }
});

const filasLeads = [...leads.values()].map((l) => {
  const motivo = l._embedded && l._embedded.loss_reason;
  return {
    fecha: fecha(l.created_at), lead_id: l.id, nombre: l.name || '', embudo_id: l.pipeline_id, etapa_id: l.status_id, valor: Number(l.price) || 0,
    origen: campo(l, (f) => f.field_name === 'Origen'), campana: campo(l, (f) => f.field_name === 'Campaña'),
    utm_source: campo(l, (f) => f.field_code === 'UTM_SOURCE'), utm_campaign: campo(l, (f) => f.field_code === 'UTM_CAMPAIGN'),
    responsable: usuarios[l.responsible_user_id] || '', motivo_perdida: Array.isArray(motivo) ? (motivo[0] && motivo[0].name) || '' : (motivo && motivo.name) || '',
    creado: iso(l.created_at), actualizado: iso(l.updated_at), cerrado: iso(l.closed_at),
  };
});

const estado = (v) => { const x = (v || [])[0]; return x && x.lead_status ? x.lead_status.id : null; };
const filasEventos = [...eventos.values()].map((ev) => ({
  fecha: fecha(ev.created_at), evento_id: String(ev.id), lead_id: ev.entity_id, de_etapa: estado(ev.value_before), a_etapa: estado(ev.value_after),
  momento: iso(ev.created_at),
})).filter((f) => f.a_etapa && rango && f.fecha >= rango.desde && f.fecha <= rango.hasta);

const hoy = dia.format(new Date());
const salida = [
  { json: { p_tabla: 'kommo_etapa', p_desde: hoy, p_hasta: hoy, p_filas: etapas, p_fuente: null, p_sitio: null } },
  { json: { p_tabla: 'kommo_lead', p_desde: hoy, p_hasta: hoy, p_filas: filasLeads, p_fuente: 'kommo', p_sitio: null } },
];
if (rango) salida.push({ json: { p_tabla: 'kommo_cambio_etapa', p_desde: rango.desde, p_hasta: rango.hasta, p_filas: filasEventos, p_fuente: 'kommo', p_sitio: null } });
return salida;

// Llena el campo Origen de Kommo cuando está vacío: el Salesbot "Origen por mensaje de WhatsApp" falla en la mayoría de
// los chats (desde el 2026-10-06 marcó 6 de 50). Reglas, en orden:
//  1. utm_source del chat (los anuncios de Meta llevan utm_source=meta_ads; los botones del sitio, instagram, facebook…).
//  2. Sin UTM, si el agente recibió un mensaje que Kommo no puede mostrar (error 131060): es el primer mensaje de un
//     anuncio de clic a WhatsApp en la coexistencia, así que se marca Meta Ads.
// Sale de "Consultar Kommo" (las mismas páginas de oportunidades) y de "Mensajes ilegibles" (Supabase).
const CAMPO_ORIGEN = 421634;
const ENUM = { instagram: 340194, ig: 340194, facebook: 340196, fb: 340196, meta_ads: 340198, meta: 340198, explee: 340200,
  email: 340202, brevo: 340202, sendinblue: 340202, sitio_web: 340204, google: 340206, google_ads: 340206, linkedin: 340208 };
const cuerpo = (j) => { if (j && typeof j.data === 'string') { try { return JSON.parse(j.data); } catch (e) { return {}; } } return j || {}; };
const leads = new Map();
for (const r of $('Consultar Kommo').all()) for (const l of (cuerpo(r.json)._embedded || {}).leads || []) leads.set(l.id, l);
const ilegibles = new Set($input.all().map((i) => Number(i.json.lead_id)).filter(Boolean));
const valor = (l, prueba) => { const f = (l.custom_fields_values || []).find(prueba); return f && f.values && f.values[0] ? String(f.values[0].value ?? '') : ''; };
const cambios = [];
for (const l of leads.values()) {
  if (valor(l, (f) => f.field_id === CAMPO_ORIGEN)) continue;
  const utm = valor(l, (f) => f.field_code === 'UTM_SOURCE').trim().toLowerCase();
  const enumId = ENUM[utm] || (!utm && ilegibles.has(l.id) ? ENUM.meta_ads : null);
  if (enumId) cambios.push({ id: l.id, custom_fields_values: [{ field_id: CAMPO_ORIGEN, values: [{ enum_id: enumId }] }] });
}
// Kommo acepta hasta 250 oportunidades por PATCH.
const lotes = [];
for (let i = 0; i < cambios.length; i += 250) lotes.push({ json: { cuerpo: cambios.slice(i, i + 250), cantidad: Math.min(250, cambios.length - i) } });
return lotes;

const LIMITE = 0; // 0 = todos; para una prueba se pone un número
const BASE = 'https://wiptool.kommo.com/api/v4';
const digitos = (t) => String(t || '').replace(/\D/g, '').slice(-10);
// "Pendientes para Kommo" devuelve una fila por lead pendiente (o un elemento vacío si no hay ninguno).
let nuevos = $input.all().map((i) => i.json).filter((f) => f.lead_id && (f.correo || digitos(f.telefono)));
if (LIMITE) nuevos = nuevos.slice(0, LIMITE);
const buscar = (q) => `${BASE}/contacts?with=leads&query=${encodeURIComponent(q)}`;
return nuevos.map((f) => ({ json: { ...f,
  url_correo: buscar(f.correo || digitos(f.telefono)),
  url_telefono: buscar(digitos(f.telefono) || f.correo) } }));

// Con lo que encontró Kommo por correo y por teléfono decide: crear la oportunidad o solo dejar la nota.
const BASE = 'https://wiptool.kommo.com/api/v4';
const EMBUDO = 14590803, ETAPA_NUEVO = 112730835, CAMPO_ORIGEN = 421634, ORIGEN_EXPLEE = 340200, CAMPO_CAMPANA = 421636;
const nuevos = $('Nuevos para Kommo').all();
const porCorreo = $('Buscar correo en Kommo').all();
const porTelefono = $input.all();
const cuerpo = (r) => {
  const j = (r && r.json) || {};
  if (typeof j.data !== 'string') return j;
  try { return JSON.parse(j.data); } catch (e) { return {}; }
};
const contactos = (r) => (cuerpo(r)._embedded || {}).contacts || [];
const campo = (code, value, enumCode) => ({ field_code: code, values: [enumCode ? { value, enum_code: enumCode } : { value }] });

return nuevos.map((n, i) => {
  const f = n.json;
  const contacto = [...contactos(porCorreo[i]), ...contactos(porTelefono[i])][0];
  const ultima = contacto && ((contacto._embedded && contacto._embedded.leads) || []).map((l) => l.id).sort((a, b) => b - a)[0];
  const base = { explee_id: f.lead_id, datos: f };
  // Ya está en Kommo: a su última oportunidad solo se le agrega la etiqueta Explee (y luego la nota).
  if (ultima) return { json: { ...base, accion: 'existente', contacto_id: contacto.id, kommo_lead_id: ultima, metodo: 'PATCH', url: `${BASE}/leads`,
    cuerpo: [{ id: ultima, tags_to_add: [{ name: 'Explee' }] }] } };

  const lead = {
    name: f.empresa || f.nombre || f.correo, pipeline_id: EMBUDO, status_id: ETAPA_NUEVO,
    custom_fields_values: [
      { field_id: CAMPO_ORIGEN, values: [{ enum_id: ORIGEN_EXPLEE }] },
      ...(f.campana ? [{ field_id: CAMPO_CAMPANA, values: [{ value: f.campana }] }] : []),
    ],
    _embedded: { tags: [{ name: 'Explee' }] },
  };
  // Fecha real del lead caliente (mediodía de Bogotá), para que el tablero lo cuente el día que respondió.
  if (f.fecha) lead.created_at = Math.floor(new Date(f.fecha + 'T12:00:00-05:00').getTime() / 1000);
  if (contacto) {
    lead._embedded.contacts = [{ id: contacto.id }];
  } else {
    lead._embedded.contacts = [{ name: f.nombre || f.correo, custom_fields_values: [
      ...(f.correo ? [campo('EMAIL', f.correo, 'WORK')] : []),
      ...(f.telefono ? [campo('PHONE', f.telefono, 'WORK')] : []),
      ...(f.cargo ? [campo('POSITION', f.cargo)] : []),
    ] }];
    if (f.empresa) lead._embedded.companies = [{ name: f.empresa, custom_fields_values: f.dominio ? [campo('WEB', f.dominio)] : [] }];
  }
  return { json: { ...base, accion: 'creado', contacto_id: contacto ? contacto.id : null, metodo: 'POST', url: `${BASE}/leads/complex`, cuerpo: [lead] } };
});

// Saca el id de la oportunidad (la creada o la que ya existía) y arma la nota con lo que respondió la persona.
const BASE = 'https://wiptool.kommo.com/api/v4';
const armados = $('Armar oportunidades').all();
const respuestas = $input.all();
const cuerpo = (r) => {
  const j = (r && r.json) || {};
  if (typeof j.data !== 'string') return j;
  try { return JSON.parse(j.data); } catch (e) { return {}; }
};
return armados.map((a, i) => {
  const x = a.json, f = x.datos;
  let leadId = x.kommo_lead_id, contactoId = x.contacto_id;
  if (x.accion === 'creado') {
    const c = cuerpo(respuestas[i]);
    const r = Array.isArray(c) ? c[0] || {} : c;
    if (!r.id) throw new Error('Kommo no devolvió la oportunidad creada para el lead de Explee ' + x.explee_id + ': ' + JSON.stringify(c).slice(0, 300));
    leadId = r.id; contactoId = r.contact_id || contactoId;
  }
  const lineas = [
    'Lead caliente de Explee' + (x.accion === 'existente' ? ' (ya estaba en Kommo)' : ''),
    `Campaña: ${f.campana || '—'} · Fecha: ${f.fecha || '—'}`,
    `Empresa: ${f.empresa || '—'}${f.dominio ? ' (' + f.dominio + ')' : ''}${f.pais ? ' · País: ' + f.pais : ''}`,
    f.cargo ? `Cargo: ${f.cargo}` : '',
    f.linkedin ? `LinkedIn: ${f.linkedin}` : '',
    f.motivo ? `Respondió: "${f.motivo}"` : '',
    f.nota ? `Nota de Explee: ${f.nota}` : '',
  ].filter(Boolean);
  return { json: {
    url: `${BASE}/leads/notes`, cuerpo: [{ entity_id: leadId, note_type: 'common', params: { text: lineas.join('\n') } }],
    fila: { lead_id: x.explee_id, kommo_lead_id: leadId, kommo_contacto_id: contactoId, accion: x.accion },
  } };
});

// Con el usuario de Calendly pide sus citas activas desde hace 2 días (las nuevas siempre son de hoy en adelante).
const usuario = ($input.first().json.resource || {}).uri;
if (!usuario) throw new Error('Calendly no devolvió el usuario: ' + JSON.stringify($input.first().json).slice(0, 200));
const desde = new Date(Date.now() - 2 * 86400000).toISOString();
return [{ json: { url: `https://api.calendly.com/scheduled_events?user=${encodeURIComponent(usuario)}&status=active&count=100&sort=start_time:asc&min_start_time=${encodeURIComponent(desde)}` } }];

// Deja solo las citas que aún no pasaron a Kommo (tabla calendly_kommo) y pide sus invitados.
const r = $('Citas Calendly').first().json;
if (r.pagination && r.pagination.next_page) throw new Error('Calendly tiene más de 100 citas activas en el periodo: hay que paginar "Citas Calendly"');
const hechas = new Set($input.all().map((i) => i.json.evento).filter(Boolean));
